use std::collections::{BTreeMap, HashMap};

use anyhow::Result;
use serde::Serialize;

use crate::player_data::Achievement;

/// Achievement id -> category (`goalId`), generated by `build.rs`.
static GOALS: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/achievement_goals.json"));

/// Achievement status 1 is unfinished, 2 is finished and 3 is finished with the
/// reward claimed.
const STATUS_FINISHED: u32 = 2;

/// Achievement tracker export: category -> achievement id -> finished.
#[derive(Serialize)]
struct AchievementExport {
    achievement: BTreeMap<u32, BTreeMap<u32, bool>>,
}

pub fn finished_ids(achievements: &[Achievement]) -> Vec<u32> {
    achievements
        .iter()
        .filter(|achievement| achievement.status >= STATUS_FINISHED)
        .map(|achievement| achievement.id)
        .collect()
}

pub fn export_achievements(achievements: &[Achievement]) -> Result<String> {
    let goals: HashMap<u32, u32> = serde_json::from_slice(GOALS)?;

    let mut export = AchievementExport {
        achievement: BTreeMap::new(),
    };
    for achievement in achievements {
        let category = goals.get(&achievement.id).copied().unwrap_or_else(|| {
            tracing::warn!("Unknown category for achievement {}", achievement.id);
            0
        });
        export
            .achievement
            .entry(category)
            .or_default()
            .insert(achievement.id, achievement.status >= STATUS_FINISHED);
    }

    Ok(serde_json::to_string(&export)?)
}
